<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="shipments shipments--<?php echo esc_attr( $mode ); ?>" id="<?php echo esc_attr( $root_id ); ?>" data-shipments aria-labelledby="<?php echo esc_attr( $title_id ); ?>"><div class="container">
  <header class="shipments__header"><h2 id="<?php echo esc_attr( $title_id ); ?>" class="shipments__title"><?php echo esc_html( $section_data['title'] ?? '' ); ?></h2><div class="shipments__description"><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div></header>
  <div class="shipments__list" data-shipments-slider tabindex="0" role="region"><?php foreach ( $items as $index => $item ) : $card_tone = array( 'warm', 'lime', 'light', 'dark', 'blue', 'gray' )[ $index % 6 ]; ?><article class="shipment-card shipment-card--<?php echo esc_attr( $mode ); ?> shipment-card_<?php echo esc_attr( $card_tone ); ?>"><div class="shipment-card__content"><h3 class="shipment-card__title"><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div class="shipment-card__text"><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div></div><?php if ( ! empty( $item['tags'] ) && is_array( $item['tags'] ) ) : ?><div class="shipment-card__tags"><?php foreach ( $item['tags'] as $tag ) : ?><span><?php echo esc_html( $tag['label'] ?? '' ); ?></span><?php endforeach; ?></div><?php endif; ?><?php if ( 'main' === $mode ) : ?><a class="shipment-card__link" href="<?php echo esc_url( $item['link']['url'] ?? '#' ); ?>"><?php echo esc_html( $item['link']['title'] ?? __( 'Подробнее', 'platejka_rework' ) ); ?></a><?php endif; ?><?php echo platejka_section_image( $item['image'] ?? 0, 'medium', array( 'class' => 'shipment-card__image' . ( 'gray' === $card_tone ? ' shipment-card__image_secure' : '' ), 'loading' => 'lazy', 'sizes' => '(max-width: 767px) 100vw, 280px', 'data-shipments-image' => '' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></article><?php endforeach; ?></div>
</div></section>
